        stake.transferFrom(msg.sender, address(this), amountIn);
        uint256 newStake = heldStake + amountIn;
        uint256 newCash = (heldStake * heldCash) / newStake;
        out = heldCash - newCash;
        heldStake = newStake;
        heldCash = newCash;
        cash.transfer(msg.sender, out);
    }
